139  void ndpi_search_tls_tcp_memory(struct ndpi_detection_module_struct *ndpi_struct,
   140                                  struct ndpi_flow_struct *flow) {
   141    struct ndpi_packet_struct *packet = &ndpi_struct->packet;
   142    u_int avail_bytes;
   143
   144    /* TCP */
   145  #ifdef DEBUG_TLS_MEMORY
   146    printf("[TLS Mem] Handling TCP/TLS flow [payload_len: %u][buffer_len: %u][direction: %u]\n",
   147           packet->payload_packet_len,
   148           flow->l4.tcp.tls.message.buffer_len,
   149           packet->packet_direction);
   150  #endif
   151
   152    if(flow->l4.tcp.tls.message.buffer == NULL) {
   153      /* Allocate buffer */
   154      flow->l4.tcp.tls.message.buffer_len = 2048, flow->l4.tcp.tls.message.buffer_used = 0;
   155      flow->l4.tcp.tls.message.buffer = (u_int8_t*)ndpi_malloc(flow->l4.tcp.tls.message.buffer_len);
   156
   157      if(flow->l4.tcp.tls.message.buffer == NULL)
   158        return;
   159
   160  #ifdef DEBUG_TLS_MEMORY
   161      printf("[TLS Mem] Allocating %u buffer\n", flow->l4.tcp.tls.message.buffer_len);
   162  #endif
   163    }
   164
   165    avail_bytes = flow->l4.tcp.tls.message.buffer_len - flow->l4.tcp.tls.message.buffer_used;
   166
   167    if(avail_bytes < packet->payload_packet_len) {
   168      u_int new_len = flow->l4.tcp.tls.message.buffer_len + packet->payload_packet_len - avail_bytes + 1;
   169      void *newbuf  = ndpi_realloc(flow->l4.tcp.tls.message.buffer,
   170                                   flow->l4.tcp.tls.message.buffer_len, new_len);
   171      if(!newbuf) return;
   172
   173  #ifdef DEBUG_TLS_MEMORY
   174      printf("[TLS Mem] Enlarging %u -> %u buffer\n", flow->l4.tcp.tls.message.buffer_len, new_len);
   175  #endif
   176
   177      flow->l4.tcp.tls.message.buffer = (u_int8_t*)newbuf;
   178      flow->l4.tcp.tls.message.buffer_len = new_len;
   179      avail_bytes = flow->l4.tcp.tls.message.buffer_len - flow->l4.tcp.tls.message.buffer_used;
   180    }
   181
   182    if(packet->payload_packet_len > 0 && avail_bytes >= packet->payload_packet_len) {
   183      u_int8_t ok = 0;
   184
   185      if(flow->l4.tcp.tls.message.next_seq[packet->packet_direction] != 0) {
   186        if(ntohl(packet->tcp->seq) == flow->l4.tcp.tls.message.next_seq[packet->packet_direction])
   187          ok = 1;
   188      } else
   189        ok = 1;
   190
   191      if(ok) {
   192        memcpy(&flow->l4.tcp.tls.message.buffer[flow->l4.tcp.tls.message.buffer_used],
   193               packet->payload, packet->payload_packet_len);
   194
   195        flow->l4.tcp.tls.message.buffer_used += packet->payload_packet_len;
   196  #ifdef DEBUG_TLS_MEMORY
   197        printf("[TLS Mem] Copied data to buffer [%u/%u bytes][direction: %u][tcp_seq: %u][next: %u]\n",
   198               flow->l4.tcp.tls.message.buffer_used, flow->l4.tcp.tls.message.buffer_len,
   199               packet->packet_direction,
   200               ntohl(packet->tcp->seq),
   201               ntohl(packet->tcp->seq)+packet->payload_packet_len);
   202  #endif
   203
   204        flow->l4.tcp.tls.message.next_seq[packet->packet_direction] = ntohl(packet->tcp->seq)+packet->payload_packet_len;
   205      } else {
   206  #ifdef DEBUG_TLS_MEMORY
   207        printf("[TLS Mem] Skipping packet [%u bytes][direction: %u][tcp_seq: %u][expected next: %u]\n",
   208               flow->l4.tcp.tls.message.buffer_len,
   209               packet->packet_direction,
   210               ntohl(packet->tcp->seq),
   211               ntohl(packet->tcp->seq)+packet->payload_packet_len);
   212  #endif
   213      }
   214    }
   215  }
